import mitt from '../lib/mitt/dist/mitt.es.js';
import { BaseModule } from '../baseModule/baseModule.js';
import { NotificationEvents } from './events.js';
import { notificationInitConfigValidator } from './validatiors.js';
import { notificationStyles } from './styles.js';
import { NotificationColorScheme } from './types.js';

const defaultConfig = {
    zIndex: 100,
    scheme: NotificationColorScheme.LIGHT,
    duration: 4000
};
class Notification extends BaseModule {
    config;
    rootId = 'vk_sdk_notification_root';
    events;
    constructor(config){
        super();
        this.config = {
            ...defaultConfig,
            ...config
        };
        const validationResult = notificationInitConfigValidator.validate({
            notificationText: config.notificationText
        });
        !validationResult.isValid() && console.error(validationResult.error());
        this.events = mitt();
        this.rootNode.id = this.rootId;
        const testIdPrefix = 'vk-sdk-notification-test-id-';
        this.contentTextNode.setAttribute('data-test-id', `${testIdPrefix}notification-text`);
        this.actionNode.setAttribute('data-test-id', `${testIdPrefix}action-button`);
        this.vkIdBlockNode.setAttribute('data-test-id', `${testIdPrefix}vk-id-block`);
        this.vkIdLogoIcon.setAttribute('data-test-id', `${testIdPrefix}vk-id-logo-icon`);
    }
    animationTiming = 320;
    svgXmlns = 'http://www.w3.org/2000/svg';
    rootNode = document.createElement('div');
    notificationNode = document.createElement('div');
    containerNode = document.createElement('div');
    bodyNode = document.createElement('div');
    beforeImageContainerNode = document.createElement('div');
    beforeImageNode = document.createElement('img');
    contentNode = document.createElement('div');
    contentTextNode = document.createElement('div');
    vkIdBlockNode = document.createElement('div');
    vkIdLogoIcon = document.createElementNS(this.svgXmlns, 'svg');
    actionNode = document.createElement('button');
    isDesktop;
    closeAnimationStartTimeoutMs;
    closeTimeoutMs;
    isTouched = false;
    isHiding = false;
    clickPosition = 0;
    addNotificationNode() {
        this.notificationNode.style.cssText = notificationStyles.notification;
        this.notificationNode.style.zIndex = this.config.zIndex.toString();
        this.rootNode.appendChild(this.notificationNode);
    }
    addContainerNode() {
        this.containerNode.style.cssText = notificationStyles.notificationContainer;
        if (this.isDesktop) {
            this.containerNode.style.maxWidth = '351px';
        }
        this.containerNode.addEventListener('mousedown', this.onTouchStart);
        this.containerNode.addEventListener('touchstart', this.onTouchStart);
        document.addEventListener('mouseup', this.onTouchEnd);
        document.addEventListener('touchend', this.onTouchEnd);
        document.addEventListener('mousemove', this.moveNotification);
        document.addEventListener('touchmove', this.moveNotification);
        this.notificationNode.appendChild(this.containerNode);
    }
    addBodyNode() {
        this.bodyNode.style.cssText = notificationStyles.notificationBody;
        if (this.config.scheme === NotificationColorScheme.LIGHT) {
            this.bodyNode.style.background = '#FFFFFF';
        }
        if (this.config.scheme === NotificationColorScheme.DARK) {
            this.bodyNode.style.background = '#303030';
        }
        if (this.isDesktop) {
            // На десктопе нотификация показывается слева
            this.containerNode.animate([
                {
                    transform: 'translate3d(-140%, 0, 0)',
                    easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                },
                {
                    transform: 'translate3d(0, 0, 0)',
                    easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                }
            ], {
                duration: this.animationTiming
            });
        }
        if (!this.isDesktop) {
            // На мобилке нотификация показывается снизу
            this.containerNode.animate([
                {
                    transform: 'translate3d(0, 140%, 0)',
                    easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                },
                {
                    transform: 'translate3d(0, 0, 0)',
                    easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                }
            ], {
                duration: this.animationTiming
            });
        }
        this.containerNode.appendChild(this.bodyNode);
    }
    addContentNode() {
        this.contentNode.style.cssText = notificationStyles.content;
        this.bodyNode.appendChild(this.contentNode);
    }
    addContentTextNode() {
        if (this.config.notificationText) {
            this.contentTextNode.style.cssText = notificationStyles.textContainer;
            if (this.config.scheme === NotificationColorScheme.LIGHT) {
                this.contentTextNode.style.color = '#2C2D2E';
            }
            if (this.config.scheme === NotificationColorScheme.DARK) {
                this.contentTextNode.style.color = '#FFFFFF';
            }
            this.contentTextNode.textContent = this.config.notificationText;
            this.contentNode.appendChild(this.contentTextNode);
        }
    }
    addVkIdBlockTextNode() {
        if (this.config.vkIdBlockText) {
            this.vkIdBlockNode.style.cssText = notificationStyles.vkIdBlock;
            this.vkIdLogoIcon.style.cssText = notificationStyles.vkIdLogoIcon;
            this.vkIdBlockNode.textContent = this.config.vkIdBlockText;
            this.vkIdLogoIcon.setAttributeNS(null, 'viewBox', '0 0 33 16');
            this.vkIdLogoIcon.setAttributeNS(null, 'width', '33');
            this.vkIdLogoIcon.setAttributeNS(null, 'height', '16');
            // Рисуем svg иконку vk id
            let pathData = [
                {
                    d: 'M20 13H21.6479V3.5H20V13Z',
                    fill: 'black',
                    style: 'fill:black;fill-opacity:1;'
                },
                {
                    d: 'M23.7801 13H27.474C30.4127 13 32.5 11.0326 32.5 8.24326C32.5' + ' 5.46738 30.4127 3.5 27.474 3.5H23.7801V13ZM25.4279 11.5177V4.98227H27.474C29.4377' + ' 4.98227 30.7835 6.31631 30.7835 8.24326C30.7835 10.1837 29.4377 11.5177 27.474 11.5177H25.4279Z',
                    fill: 'black',
                    style: 'fill:black;fill-opacity:1;'
                },
                {
                    d: 'M0 7.68C0 4.05961 0 2.24942 1.12471 1.12471C2.24942 0 4.05961 0 7.68' + ' 0H8.32C11.9404 0 13.7506 0 14.8753 1.12471C16 2.24942 16 4.05961 16' + ' 7.68V8.32C16 11.9404 16 13.7506 14.8753 14.8753C13.7506 16 11.9404 16 8.32 16H7.68C4.05961' + ' 16 2.24942 16 1.12471 14.8753C0 13.7506 0 11.9404 0 8.32V7.68Z',
                    fill: '#0077FF',
                    style: 'fill:#0077FF;fill:color(display-p3 0.0000 0.4667 1.0000);fill-opacity:1;'
                },
                {
                    d: 'M8.56331 11.66C4.91665 11.66 2.83667 9.16 2.75 5H4.57666C4.63666 8.05333' + ' 5.9833 9.34333 7.04997 9.61V5H8.77002V7.63C9.82335 7.51667 10.9299 6.32 11.3032 5H13.0233C12.7366' + ' 6.62667 11.5366 7.82667 10.6833 8.32C11.5366 8.72 12.9033 9.76667 13.4233 11.66H11.5299C11.1233' + ' 10.3933 10.11 9.41333 8.77002 9.28V11.66H8.56331Z',
                    fill: '#0077FF',
                    style: 'fill:white;fill-opacity:1;'
                }
            ];
            if (this.config.scheme === NotificationColorScheme.DARK) {
                pathData = [
                    {
                        d: 'M20 13H21.6479V3.5H20V13Z',
                        fill: 'white',
                        style: 'fill:white;fill-opacity:1;'
                    },
                    {
                        d: 'M23.7801 13H27.474C30.4127 13 32.5 11.0326 32.5 8.24326C32.5' + ' 5.46738 30.4127 3.5 27.474 3.5H23.7801V13ZM25.4279 11.5177V4.98227H27.474C29.4377' + ' 4.98227 30.7835 6.31631 30.7835 8.24326C30.7835 10.1837 29.4377 11.5177 27.474 11.5177H25.4279Z',
                        fill: 'white',
                        style: 'fill:white;fill-opacity:1;'
                    },
                    {
                        d: 'M0 7.68C0 4.05961 0 2.24942 1.12471 1.12471C2.24942 0 4.05961 0 7.68' + ' 0H8.32C11.9404 0 13.7506 0 14.8753 1.12471C16 2.24942 16 4.05961 16' + ' 7.68V8.32C16 11.9404 16 13.7506 14.8753 14.8753C13.7506 16 11.9404 16 8.32 16H7.68C4.05961' + ' 16 2.24942 16 1.12471 14.8753C0 13.7506 0 11.9404 0 8.32V7.68Z',
                        fill: '#0077FF',
                        style: 'fill:#0077FF;fill:color(display-p3 0.0000 0.4667 1.0000);fill-opacity:1;'
                    },
                    {
                        d: 'M8.56331 11.66C4.91665 11.66 2.83667 9.16 2.75 5H4.57666C4.63666 8.05333' + ' 5.9833 9.34333 7.04997 9.61V5H8.77002V7.63C9.82335 7.51667 10.9299 6.32 11.3032 5H13.0233C12.7366' + ' 6.62667 11.5366 7.82667 10.6833 8.32C11.5366 8.72 12.9033 9.76667 13.4233 11.66H11.5299C11.1233' + ' 10.3933 10.11 9.41333 8.77002 9.28V11.66H8.56331Z',
                        fill: '#0077FF',
                        style: 'fill:white;fill-opacity:1;'
                    }
                ];
            }
            for (let data of pathData){
                const pathNode = document.createElementNS(this.svgXmlns, 'path');
                pathNode.setAttributeNS(null, 'd', data.d);
                pathNode.setAttributeNS(null, 'fill', data.fill);
                pathNode.setAttributeNS(null, 'style', data.style);
                this.vkIdLogoIcon.appendChild(pathNode);
            }
            this.vkIdBlockNode.appendChild(this.vkIdLogoIcon);
            this.contentNode.appendChild(this.vkIdBlockNode);
        }
    }
    addActionNode() {
        if (this.config.actionButtonText) {
            this.actionNode.style.cssText = notificationStyles.action;
            if (this.config.scheme === NotificationColorScheme.LIGHT) {
                this.actionNode.style.color = '#447bba';
            }
            if (this.config.scheme === NotificationColorScheme.DARK) {
                this.actionNode.style.color = '#FFFFFF';
            }
            this.actionNode.textContent = this.config.actionButtonText;
            this.actionNode.addEventListener('click', this.actionButtonClickHandler);
            this.contentNode.appendChild(this.actionNode);
        }
    }
    handleBridgeMessage(data) {
        super.handleBridgeMessage(data);
    }
    addBeforeImageNode() {
        if (this.config.beforeImageUrl) {
            this.beforeImageContainerNode.style.cssText = notificationStyles.avatarContainer;
            this.bodyNode.appendChild(this.beforeImageContainerNode);
            this.beforeImageNode.style.cssText = notificationStyles.avatar;
            this.beforeImageNode.src = this.config.beforeImageUrl;
            this.beforeImageContainerNode.appendChild(this.beforeImageNode);
        }
    }
    hideNotificationAuto() {
        if (this.closeAnimationStartTimeoutMs) {
            clearTimeout(this.closeAnimationStartTimeoutMs);
        }
        this.closeAnimationStartTimeoutMs = setTimeout(()=>{
            this.isHiding = true;
            this.isTouched = false;
            if (this.isDesktop) {
                // На десктопе анимация скрытия - нотификация уезжает влево
                this.containerNode.animate([
                    {
                        transform: 'translate3d(0, 0, 0)',
                        easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                    },
                    {
                        transform: 'translate3d(-140%, 0, 0)',
                        easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                    }
                ], {
                    duration: this.animationTiming
                });
            }
            if (!this.isDesktop) {
                // На мобилке анимация скрытия - нотификация уезжает вниз
                this.containerNode.animate([
                    {
                        transform: 'translate3d(0, 0, 0)',
                        easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                    },
                    {
                        transform: 'translate3d(0, 140%, 0)',
                        easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                    }
                ], {
                    duration: this.animationTiming
                });
            }
        }, this.config.duration, this);
        if (this.closeTimeoutMs) {
            clearTimeout(this.closeTimeoutMs);
        }
        this.closeTimeoutMs = setTimeout(()=>{
            this.removeNotification();
        }, this.config.duration + this.animationTiming, this);
    }
    onTouchStart = (e)=>{
        e.stopPropagation();
        this.isTouched = true;
        if (e instanceof TouchEvent) {
            this.clickPosition = e.touches[0].clientX;
        }
        if (e instanceof MouseEvent) {
            this.clickPosition = e.clientX;
        }
        if (!this.isHiding) {
            if (this.closeTimeoutMs) {
                clearTimeout(this.closeTimeoutMs);
            }
            if (this.closeAnimationStartTimeoutMs) {
                clearTimeout(this.closeAnimationStartTimeoutMs);
            }
        }
    };
    onTouchEnd = ()=>{
        const containerSizes = this.containerNode.getBoundingClientRect();
        const viewWidth = Math.max(document.documentElement.clientWidth || 0, window.innerWidth || 0);
        const desktopCloseBreakpoint = containerSizes.x < 0 && Math.abs(containerSizes.x) >= containerSizes.width / 2 && this.isDesktop;
        const mobileCloseBreakpoint = containerSizes.x + containerSizes.width / 2 >= viewWidth && !this.isDesktop;
        if (desktopCloseBreakpoint || mobileCloseBreakpoint) {
            // если пользователь смахнул - проигрываем анимацию и удаляем нотификацию
            this.isHiding = true;
            if (this.isDesktop) {
                // Для десктопа смахивание влево
                this.containerNode.animate([
                    {
                        transform: `translate3d(${containerSizes.x}, 0, 0)`,
                        easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                    },
                    {
                        transform: 'translate3d(-140%, 0, 0)',
                        easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                    }
                ], {
                    duration: this.animationTiming
                });
            }
            if (!this.isDesktop) {
                // Для мобилки смахивание вправо
                this.containerNode.animate([
                    {
                        transform: `translate3d(${containerSizes.x}, 0, 0)`,
                        easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                    },
                    {
                        transform: 'translate3d(140%, 0, 0)',
                        easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                    }
                ], {
                    duration: this.animationTiming
                });
            }
            if (this.closeTimeoutMs) {
                clearTimeout(this.closeTimeoutMs);
            }
            this.closeTimeoutMs = setTimeout(()=>{
                this.removeNotification();
            }, this.animationTiming, this);
        } else if (this.isTouched) {
            // Если смахнул не до конца, то возвращаем нотификацию на место, перезапускаем таймеры скрытия
            this.containerNode.animate([
                {
                    transform: `translate3d(${containerSizes.x}px, 0, 0)`,
                    easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                },
                {
                    transform: 'translate3d(0, 0, 0)',
                    easing: 'cubic-bezier(0.3, 0.3, 0.5, 1)'
                }
            ], {
                duration: this.animationTiming
            });
            this.containerNode.style.transform = 'translate3d(0, 0, 0)';
            this.hideNotificationAuto();
        }
        this.isTouched = false;
    };
    moveNotification = (e)=>{
        if (this.isTouched) {
            let clientX = 0;
            if (e instanceof MouseEvent) {
                clientX = e.clientX;
            }
            if (e instanceof TouchEvent) {
                clientX = e.touches[0].clientX;
            }
            this.containerNode.style.transform = `translate3d(${clientX - this.clickPosition}px, 0, 0)`;
        }
    };
    actionButtonClickHandler = ()=>{
        this.events.emit(NotificationEvents.ACTION_BUTTON_CLICK);
    };
    removeNotification() {
        if (document.getElementById(this.rootId)) {
            this.containerNode.removeEventListener('mousedown', this.onTouchStart);
            this.containerNode.removeEventListener('touchstart', this.onTouchStart);
            this.actionNode.removeEventListener('click', this.actionButtonClickHandler);
            document.removeEventListener('mouseup', this.onTouchEnd);
            document.removeEventListener('touchend', this.onTouchEnd);
            document.removeEventListener('mousemove', (e)=>this.moveNotification(e));
            document.removeEventListener('touchmove', (e)=>this.moveNotification(e));
            document.body.removeChild(this.rootNode);
        }
    }
    close() {
        if (this.closeTimeoutMs) {
            clearTimeout(this.closeTimeoutMs);
        }
        if (this.closeAnimationStartTimeoutMs) {
            clearTimeout(this.closeAnimationStartTimeoutMs);
        }
        this.removeNotification();
    }
    async open() {
        if (document.getElementById(this.rootId)) {
            return Promise.resolve();
        }
        const viewWidth = Math.max(document.documentElement.clientWidth || 0, window.innerWidth || 0);
        this.isDesktop = viewWidth >= 768;
        this.isHiding = false;
        this.addBeforeImageNode();
        this.addContentTextNode();
        this.addContentNode();
        this.addVkIdBlockTextNode();
        this.addActionNode();
        this.addBodyNode();
        this.addContainerNode();
        this.addNotificationNode();
        document.body.appendChild(this.rootNode);
        this.hideNotificationAuto();
        return Promise.resolve();
    }
    /**
   * @deprecated
   */ update() {
        return;
    }
    /**
   * @deprecated
   */ sendMessage() {
        return;
    }
    /**
   * @deprecated
   */ preload() {
        return Promise.resolve();
    }
}

export { Notification };
