import { isActionValid } from '../auth/validators.js';
import { VERSION, LANGUAGES } from '../common/constants.js';
import { hasAllowedAppSettingsParams, makeAppSettingsString, makeParams } from '../common/utils.js';
import { Config } from '../config/config.js';

function makeAuthActionString(authAction) {
    if (isActionValid(authAction)) {
        return btoa(JSON.stringify(authAction));
    }
    return '';
}
const CONNECT_AUTH_RESPONSE_TYPE = 'silent_token';
function makeAuthUrl(params, authPage = 'auth') {
    return Config.fetchDomain().then(()=>{
        const { appId, connectDomain, appSettings, _debug, _localhost } = Config.get();
        const urlParamsObj = {
            app_id: appId,
            response_type: CONNECT_AUTH_RESPONSE_TYPE,
            v: VERSION,
            debug: _debug ? 1 : null,
            localhost: _localhost ? 1 : null,
            ...params
        };
        if (appSettings && hasAllowedAppSettingsParams(appSettings)) {
            urlParamsObj.app_settings = makeAppSettingsString(appSettings);
        }
        const urlParams = makeParams(urlParamsObj);
        return Promise.resolve(`https://${connectDomain}/${authPage}?${urlParams}`);
    });
}
const allowedLanguages = [
    LANGUAGES.RUS,
    LANGUAGES.UKR,
    LANGUAGES.ENG,
    LANGUAGES.SPA,
    LANGUAGES.GERMAN,
    LANGUAGES.POL,
    LANGUAGES.FRA,
    LANGUAGES.TURKEY
];

export { CONNECT_AUTH_RESPONSE_TYPE, allowedLanguages, makeAuthActionString, makeAuthUrl };
