import { initTracerError, initTracerErrorAsyncStack, initTracerErrorUploader } from '@apptracer/sdk';

import { tracerAppToken } from '../../config';

export const initTracer = () => {
  const config = {
    versionName: 'vks-chat-widget',
    versionCode: 1,
    appToken: tracerAppToken,
    environment: 'production',
  };

  // Логируем ошибки в асинхронном коде
  initTracerErrorAsyncStack();

  // Подписываемся на глобальные события ошибок
  initTracerError();

  // Инициализируем Трейсер для отправки зарегистрированных ошибок
  initTracerErrorUploader(config);
};
