import { CommonErrorReasons } from '../common/errors.js';
import { isRequiredHandler } from '../validator/validationRuleHandlers.js';
import { Validator } from '../validator/validator.js';

const notificationInitConfigValidator = new Validator({
    notificationText: [
        {
            rule: isRequiredHandler,
            errorText: CommonErrorReasons.validationIsRequired('notificationText')
        }
    ]
});

export { notificationInitConfigValidator };
