/* eslint-disable no-console */
import { storageManager } from './storageManager';

/** Gets wuuid param (widget settings) from storage */
export const getWidgetUuidQuery = () => {
  try {
    return storageManager?.getItem('wuuid') || null;
  } catch (error) {
    console.error('Error getting widget UUID from storage:', error);
    return null;
  }
};
