import { CommonErrorReasons } from '../common/errors.js';
import { isStringHandler, isRequiredHandler } from '../validator/validationRuleHandlers.js';
import { Validator } from '../validator/validator.js';

const redirectAuthValidator = new Validator({
    url: [
        {
            rule: isStringHandler,
            errorText: CommonErrorReasons.validationIsString('url')
        },
        {
            rule: isRequiredHandler,
            errorText: CommonErrorReasons.validationIsRequired('url')
        }
    ]
});
const uuidValidator = new Validator({
    uuid: [
        {
            rule: isStringHandler,
            errorText: CommonErrorReasons.validationIsString('uuid')
        },
        {
            rule: isRequiredHandler,
            errorText: CommonErrorReasons.validationIsRequired('uuid')
        }
    ]
});

export { redirectAuthValidator, uuidValidator };
