class PendingTask {
    resolveHandler;
    rejectHandler;
    promise;
    finished;
    active;
    start() {
        this.active = true;
        this.finished = false;
        this.promise = new Promise((resolve, reject)=>{
            this.resolveHandler = resolve;
            this.rejectHandler = reject;
        });
    }
    get() {
        return this.promise;
    }
    resolve = (data)=>{
        if (!Boolean(this.promise)) {
            return;
        }
        this.finished = true;
        this.active = false;
        return this.resolveHandler(data);
    };
    reject = (data)=>{
        if (!Boolean(this.promise)) {
            return;
        }
        this.finished = true;
        this.active = false;
        return this.rejectHandler(data);
    };
}

export { PendingTask as default };
